struct Node;

use crate::aap::caps::inference_llm;

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Build the model's material from the kept entries only.
        let mut prompt = String::new();
        prompt.push_str("Date: ");
        prompt.push_str(&info.date);
        prompt.push('\n');
        for e in &selected.entries {
            if e.kept {
                prompt.push_str("- ");
                prompt.push_str(&e.title);
                prompt.push_str(": ");
                prompt.push_str(&e.summary);
                prompt.push('\n');
            }
        }

        let system =
            "Write a single concise overview of the day's kept items, at most 600 characters.";

        // The only authority this node holds: model access, no tools.
        let raw = inference_llm::infer(system, &prompt, "digest");

        // ensures len(overview) <= 600 (characters, matching Python's len).
        let overview: String = raw.chars().take(600).collect();

        // ensures len(date) == 10: carry the input date through unchanged.
        // The `requires len(in1.date) == 10` guarantees this holds of the output.
        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
